INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_002_001", "vo_minigame_1013_icon_2_002_001", 2, 2, 2, 3000, 1, 1000, "訓練はまだ\nここからですわ", "調子が上がって\nきたなっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_003_001", "vo_minigame_1013_icon_2_003_001", 2, 2, 2, 3000, 2, 5000, "クスクス、悪くない\n流れですわね", "ほらほら、\nまだいけるだろ？");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_004_001", "vo_minigame_1013_icon_2_004_001", 2, 3, 2, 3000, 3, 10000, "すばらしい\n記録ですわ", "へへっ、おまえら\nやるじゃねえか！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_005_001", "vo_minigame_1013_icon_2_005_001", 3, 3, 2, 3000, 4, 10000, "乗りに乗って\nいますわね", "あたしたちはまだ\n止まらねえぜ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_005_002", "vo_minigame_1013_icon_2_005_002", 3, 3, 2, 3000, 5, 10000, "まだまだ行きます\nついてきなさい", "見てろよ！\nマコト班の快進撃だ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_005_003", "vo_minigame_1013_icon_2_005_003", 3, 3, 2, 3000, 6, 10000, "エリコ班の\n本領発揮ですわ！", "うおぉぉっ！\n絶好調だぜ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_006_001", "vo_minigame_1013_icon_2_006_001", 4, 3, 2, 3000, 7, 0, "ここからは\n前人未到の領域です！", "どこまで行けるか\n楽しみだなっ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_007_001", "vo_minigame_1013_icon_2_007_001", 5, 4, 3, 1000, 8, 1, "厄介でしたわ…", "まだ諦めんなよっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_007_002", "vo_minigame_1013_icon_2_007_002", 5, 4, 3, 1000, 9, 1, "油断大敵です", "冷やっとしたぜ…！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_007_003", "vo_minigame_1013_icon_2_007_003", 5, 4, 3, 1000, 10, 1, "忌々しいっ…", "弱音を吐くなっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_008_001", "vo_minigame_1013_icon_2_008_001", 6, 3, 4, 1500, 11, 99, "大所帯ですわね", "マコト班集合！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_008_002", "vo_minigame_1013_icon_2_008_002", 6, 3, 4, 1500, 12, 99, "エリコ班へようこそ", "連携してくぞ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_020_001", "vo_minigame_1013_icon_2_020_001", 8, 6, 1, 3000, 13, 0, "ナナカちゃんに\nお任せあれ", "みんなに力を！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_022_001", "vo_minigame_1013_icon_2_022_001", 9, 7, 1, 3000, 14, 0, "はっはっは！\n任せろ！", "任せてくれたまえ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES ("vo_minigame_1013_icon_1_023_001", "vo_minigame_1013_icon_2_023_001", 10, 8, 1, 3000, 15, 0, "どんどんいくわよ", "ほな、いきまひょか");
